    H,W=len(grid),len(grid[0])
    cyc=list(grid[0])
    for X in sorted(set(v for r in grid for v in r)):
        rc=[None if v==X else v for v in cyc]
        # row0 minus X-cells should be exactly periodic; find minimal p
        for p in range(1,W+1):
            if all(rc[j]==rc[j%p] for j in range(W)):
                out=[r[:] for r in grid]
                for i in range(H):
                    for j in range(W):
                        if grid[i][j]==X: out[i][j]=cyc[(i+j)%p]
                return out,cyc,p,X
    return None,None,None,None

